CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Alphabetical list of products` AS select `Products`.`CategoryID` AS `CategoryID`,`Products`.`Discontinued` AS `Discontinued`,`Products`.`ProductID` AS `ProductID`,`Products`.`ProductName` AS `ProductName`,`Products`.`QuantityPerUnit` AS `QuantityPerUnit`,`Products`.`ReorderLevel` AS `ReorderLevel`,`Products`.`SupplierID` AS `SupplierID`,`Products`.`UnitPrice` AS `UnitPrice`,`Products`.`UnitsInStock` AS `UnitsInStock`,`Products`.`UnitsOnOrder` AS `UnitsOnOrder`,`Categories`.`CategoryName` AS `CategoryName` from (`Categories` join `Products` on((`Categories`.`CategoryID` = `Products`.`CategoryID`))) where (`Products`.`Discontinued` = 0);
